// Replays the builder block of proto/testdata/openai_model_vectors.json
// (generated by proto/go/zs/handler/openai_model_vectors_test.go) against
// proto/ts/src/inject/openaimodel.ts. The SDK replays the cases block, which
// runs this builder behind its fee gross-up.

import { describe, it, expect } from 'vitest'
import * as fs from 'node:fs'
import * as path from 'node:path'
import { fileURLToPath } from 'node:url'

import { openAIModelFromDetails, type OperatorDetailsModel } from '../src/inject/index.js'

const here = path.dirname(fileURLToPath(import.meta.url))
const vectors = JSON.parse(fs.readFileSync(path.join(here, '../../testdata/openai_model_vectors.json'), 'utf8')) as {
  owned_by: string
  builder_created: number
  builder: { name: string; details: OperatorDetailsModel; want: unknown }[]
}

describe('openai_model vectors: builder', () => {
  it.each(vectors.builder.map((c) => [c.name, c] as const))('%s', (_, c) => {
    expect(openAIModelFromDetails(c.details, vectors.owned_by, vectors.builder_created)).toEqual(c.want)
  })
})
